<?php require_once __DIR__.'/includes/bootstrap.php';require_login();$u=current_user();if($u['role']==='admin')$st=$pdo->query('SELECT o.*,u.name buyer FROM orders o JOIN users u ON u.id=o.buyer_id ORDER BY o.created_at DESC');elseif($u['role']==='farmer'){$st=$pdo->prepare('SELECT DISTINCT o.*,u.name buyer FROM orders o JOIN users u ON u.id=o.buyer_id JOIN order_items oi ON oi.order_id=o.id WHERE oi.farmer_id=? ORDER BY o.created_at DESC');$st->execute([$u['id']]);}else{$st=$pdo->prepare('SELECT * FROM orders WHERE buyer_id=? ORDER BY created_at DESC');$st->execute([$u['id']]);}$orders=$st->fetchAll();include __DIR__.'/includes/header.php'; ?>
<section class="page-banner"><span class="eyebrow">ORDER HISTORY</span><h1><?= $u['role']==='farmer'?'Orders containing your produce':'Your orders' ?></h1></section><section class="section"><div class="panel table-wrap"><table><thead><tr><th>Order</th><?php if($u['role']!=='buyer'): ?><th>Buyer</th><?php endif; ?><th>Date</th><th>Total</th><th>Status</th><th>Receipt</th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td>#<?= $o['id'] ?></td><?php if($u['role']!=='buyer'): ?><td><?= e($o['buyer']) ?></td><?php endif; ?><td><?= e($o['created_at']) ?></td><td>KSh <?= number_format($o['total'],2) ?></td><td><span class="status"><?= e(ucwords(str_replace('_',' ',$o['status']))) ?></span></td><td><a href="receipt.php?id=<?= $o['id'] ?>">View / print</a></td></tr><?php endforeach; ?><?php if(!$orders): ?><tr><td colspan="6">No orders yet.</td></tr><?php endif; ?></tbody></table></div></section><?php include __DIR__.'/includes/footer.php'; ?>